import{_ as a,o as d,c as e,a0 as r}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Modules","description":"","frontmatter":{},"headers":[],"relativePath":"modules/syntax/index.md","filePath":"modules/syntax/index.md"}'),o={name:"modules/syntax/index.md"};function s(i,t,m,p,n,l){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h1><p>Dokumentasi modul bawaan Rupa. Semua modul diakses melalui import:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import math from rupa</span></span>
<span class="line"><span>import os from rupa</span></span>
<span class="line"><span>import { join, base } from rupa.sys</span></span></code></pre></div><p>Modul yang bisa ditulis dengan bahasa Rupa ditulis di <code>stdlib/</code> (mis. <code>math</code>, <code>sys</code>); yang butuh akses sistem ditulis sebagai native module di <code>src/stdlib/</code> (mis. <code>os</code>, <code>io</code>, <code>thread</code>).</p><h2 id="daftar-modul" tabindex="-1">Daftar modul <a class="header-anchor" href="#daftar-modul" aria-label="Permalink to &quot;Daftar modul&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modul</th><th>Import</th><th>Fungsi utama</th></tr></thead><tbody><tr><td><a href="./math.html">math</a></td><td><code>import math from rupa</code></td><td>abs, min, max, floor, ceil, round, sqrt, pow, random</td></tr><tr><td><a href="./os.html">os</a></td><td><code>import os from rupa</code></td><td>exec, getcwd, getenv, chdir, mkdir, listdir, info</td></tr><tr><td><a href="./io.html">io</a></td><td><code>import io from rupa</code></td><td>input, toNumber</td></tr><tr><td><a href="./json.html">json</a></td><td><code>import json from rupa</code></td><td>stringify, parse</td></tr><tr><td><a href="./string.html">string</a></td><td><code>import string from rupa</code></td><td>split, join, trim, replace, dsb.</td></tr><tr><td><a href="./thread.html">thread</a></td><td><code>import thread from rupa</code></td><td>create, join, sleep</td></tr><tr><td><a href="./http.html">http</a></td><td><code>import http from rupa</code></td><td>request, server (listen, route)</td></tr><tr><td><a href="./datetime.html">datetime</a></td><td><code>import datetime from rupa</code></td><td>now, format, timestamp</td></tr><tr><td><a href="./regex.html">regex</a></td><td><code>import regex from rupa</code></td><td>match, test, replace, groups</td></tr><tr><td><a href="./crypto.html">crypto</a></td><td><code>import crypto from rupa</code></td><td>hash (sha256, md5), hmac, random</td></tr><tr><td><a href="./net.html">net</a></td><td><code>import net from rupa</code></td><td>TCP client/server</td></tr><tr><td><a href="./sys.html">sys</a></td><td><code>import sys from rupa</code></td><td>env, cwd, platform, arch, path utilities</td></tr><tr><td><a href="./fs.html">fs</a></td><td><code>import fs from rupa</code></td><td>read, write, append, exists, isDir</td></tr><tr><td><a href="./database.html">database</a></td><td><code>import database from rupa</code></td><td>penyedia koneksi driver (nosql, mariadb, psql, mysql, sqlite)</td></tr></tbody></table><p>Sintaks import/export lengkap: <a href="./../../syntax/import.html">Syntax — Import</a>, <a href="./../../syntax/export.html">Syntax — Export</a>. Grammar implementasi: <a href="./../../grammar/module.html">Grammar — Module</a>.</p>`,7)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
